-- ===========================================================================
-- 0026_hard_skill_profesi.sql
--
-- Hard skill per profesi: kemampuan teknis yang dilihat pengguna di tab
-- "Skill & Kompetensi" dan di lembar Skill Gap Analysis.
--
-- Kenapa tidak ditulis tangan
-- ---------------------------
-- Desain meminta 8 kemampuan teknis per profesi. Untuk 477 profesi itu
-- 3.816 kalimat yang harus benar secara faktual. Menuliskannya sendiri
-- berarti mengarang isi pekerjaan orang.
--
-- O*NET sudah memilikinya. Tiap SOC punya daftar Task Statement, tiap task
-- ditandai satu atau lebih Detailed Work Activity (DWA), dan tiap task
-- punya skor Importance 1-5. Rata-rata importance task yang menunjuk sebuah
-- DWA memberi peringkat: kemampuan mana yang paling menentukan profesi itu.
--
-- Kita ambil 8 DWA teratas per SOC. Hasilnya 3.700 tautan yang hanya memakai
-- 1.199 DWA berbeda -- jadi menerjemahkan 1.199 kalimat sekali memberi hard
-- skill berbahasa Indonesia untuk seluruh 464 SOC, persis pola yang dipakai
-- 0006 untuk milestone (311 IWA) dan 0015 untuk kemampuan alat.
--
-- Deskripsi diambil dari IWA induk DWA tersebut, yang sudah diterjemahkan di
-- 0006 (292 IWA yang dibutuhkan, semuanya sudah ada). Jadi deskripsi tidak
-- menambah biaya terjemahan sama sekali, dan ia menjelaskan kelompok
-- kemampuan yang lebih luas tempat skill itu berada -- persis fungsi baris
-- abu-abu di bawah nama skill pada desain.
--
-- Catatan register: desainer menulis nama kompetensi bermerek ("Surgical
-- Scrubbing & Gowning"). Yang diturunkan di sini berbunyi seperti aktivitas
-- ("Menjaga sterilitas area operasi"). Isinya sama-sama spesifik dan nyata,
-- tapi nadanya beda. is_curated menandai baris yang kelak dipoles manusia.
-- ===========================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Kosakata hard skill (DWA O*NET)
-- ---------------------------------------------------------------------------
create table if not exists public.hard_skill_items (
  code        text primary key,              -- DWA Element ID, mis. '4.A.3.a.1.i.1'
  iwa_code    text        not null references public.roadmap_skill_areas(code),
  name_id     text        not null,          -- yang dilihat pengguna
  name_en     text        not null,          -- teks O*NET asli, jejak sumber
  is_curated  boolean     not null default false,
  created_at  timestamptz not null default now()
);

comment on table public.hard_skill_items is
  'Kosakata kemampuan teknis, 1:1 dengan Detailed Work Activity O*NET. name_en disimpan supaya terjemahan bisa diaudit.';
comment on column public.hard_skill_items.iwa_code is
  'IWA induk. Terjemahan Indonesianya dipakai sebagai deskripsi skill.';
comment on column public.hard_skill_items.is_curated is
  'true kalau nama Indonesianya sudah dipoles manusia ke register kompetensi.';

alter table public.hard_skill_items enable row level security;
drop policy if exists hard_skill_items_read_all on public.hard_skill_items;
create policy hard_skill_items_read_all on public.hard_skill_items
  for select to anon, authenticated using (true);

-- ---------------------------------------------------------------------------
-- 2. Tautan profesi -> hard skill
-- ---------------------------------------------------------------------------
create table if not exists public.career_hard_skill_items (
  career_id     integer  not null references public.careers(id) on delete cascade,
  skill_code    text     not null references public.hard_skill_items(code) on delete cascade,
  importance    numeric(4,2) not null,       -- rata-rata Importance task O*NET, skala 1-5
  display_order smallint not null,           -- 1 = paling menentukan
  primary key (career_id, skill_code)
);

comment on table public.career_hard_skill_items is
  'Delapan kemampuan teknis paling menentukan per profesi, diurutkan dari rata-rata Importance task O*NET.';

create index if not exists idx_chsi_career
  on public.career_hard_skill_items (career_id, display_order);

alter table public.career_hard_skill_items enable row level security;
drop policy if exists career_hard_skill_items_read_all on public.career_hard_skill_items;
create policy career_hard_skill_items_read_all on public.career_hard_skill_items
  for select to anon, authenticated using (true);

-- ---------------------------------------------------------------------------
-- 3. Isi kosakata
-- ---------------------------------------------------------------------------
