-- ---------------------------------------------------------------------------
-- 4. Tautan per SOC
--
--    Ditulis per SOC, lalu disebar ke tiap profesi yang memetakan ke SOC itu.
--    Anggota satu keluarga (mis. sembilan varian Perawat) memang berbagi SOC,
--    jadi mereka berbagi hard skill juga -- yang membedakan mereka adalah
--    sub-industri, gaji, dan lisensi, bukan aktivitas teknis intinya.
-- ---------------------------------------------------------------------------
create temporary table _soc_skill (
  soc_code      text,
  skill_code    text,
  importance    numeric(4,2),
  display_order smallint
) on commit drop;

