delete from public.career_hard_skill_items;

-- careers.soc_code adalah tautan utama; career_onet_map hanya menampung 35
-- pemetaan manual untuk profesi yang tidak punya soc_code sendiri.
insert into public.career_hard_skill_items (career_id, skill_code, importance, display_order)
select c.id, s.skill_code, s.importance, s.display_order
from public.careers c
left join public.career_onet_map m on m.career_id = c.id
join _soc_skill s on s.soc_code = coalesce(c.soc_code, m.soc_code)
where c.is_active
on conflict (career_id, skill_code) do nothing;

-- ---------------------------------------------------------------------------
-- 5. Tampilan siap pakai untuk layar
-- ---------------------------------------------------------------------------
create or replace view public.career_hard_skill_view
with (security_invoker = true) as
select
  chs.career_id,
  chs.display_order,
  hsi.code            as skill_code,
  hsi.name_id         as nama,
  rsa.name_id         as deskripsi,
  chs.importance
from public.career_hard_skill_items chs
join public.hard_skill_items hsi     on hsi.code = chs.skill_code
join public.roadmap_skill_areas rsa  on rsa.code = hsi.iwa_code;

comment on view public.career_hard_skill_view is
  'Hard skill per profesi lengkap dengan deskripsi dari IWA induk, siap dipakai tab Skill & Kompetensi.';

-- ---------------------------------------------------------------------------
-- 6. Penjaga
--
--    Layar menampilkan 3 skill lalu "Lihat Semua Ketrampilan (+5)". Kalau ada
--    profesi aktif yang punya kurang dari 4 skill, tombol itu bohong.
-- ---------------------------------------------------------------------------
do $$
declare
  v_kurang int;
  v_kosong int;
begin
  select count(*) into v_kosong
  from public.careers c
  where c.is_active
    and not exists (select 1 from public.career_hard_skill_items x where x.career_id = c.id);

  if v_kosong > 0 then
    raise exception '0026: % profesi aktif tanpa hard skill sama sekali', v_kosong;
  end if;

  select count(*) into v_kurang from (
    select chs.career_id
    from public.career_hard_skill_items chs
    join public.careers c on c.id = chs.career_id and c.is_active
    group by chs.career_id
    having count(*) < 4
  ) x;

  if v_kurang > 0 then
    raise exception '0026: % profesi punya kurang dari 4 hard skill, tombol "Lihat Semua" akan salah', v_kurang;
  end if;

  raise notice '0026: % kosakata hard skill, % tautan profesi',
    (select count(*) from public.hard_skill_items),
    (select count(*) from public.career_hard_skill_items);
end $$;

commit;
